export const SITE_STYLE_CSS = "/* Lupa — editorial research design. Self-hosted fonts in fonts.css. */\n:root{\n  --paper:#f6f3ec; --paper-2:#efeadf; --card:#fffdf8; --ink:#14201e; --ink-2:#33413e; --muted:#5f6b67;\n  --rule:#ddd6c8; --rule-2:#c9c0ae; --deep:#0b1f1d; --deep-2:#12302c; --teal:#0e5a50; --teal-2:#0a463e;\n  --amber:#c9852a; --amber-ink:#8a5410; --amber-soft:#f6e6cb;\n  --up:#137a4b; --down:#b3261e; --up-l:#5fd39a; --down-l:#ff8a80;\n  --serif:\"Newsreader\",Georgia,\"Times New Roman\",serif; --sans:\"IBM Plex Sans\",system-ui,-apple-system,\"Segoe UI\",sans-serif; --mono:\"IBM Plex Mono\",ui-monospace,Menlo,monospace;\n  --r:14px; --r-sm:8px; --shadow:0 1px 2px rgba(20,32,30,.06),0 8px 24px -12px rgba(20,32,30,.18);\n  --maxw:76rem; --gut:clamp(1rem,3.5vw,2rem);\n}\n*,*::before,*::after{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;scroll-padding-top:7rem}\nbody{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:1rem;line-height:1.55;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}\nimg,svg,picture{display:block;max-width:100%}\nimg{height:auto}\na{color:var(--teal);text-decoration-thickness:1px;text-underline-offset:.18em}\na:hover{color:var(--teal-2);text-decoration-thickness:2px}\n:focus-visible{outline:3px solid var(--amber);outline-offset:3px;border-radius:4px}\n.sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n.wrap{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut)}\n.skip{position:absolute;left:-999px;top:.5rem;z-index:100;background:var(--ink);color:#fff;padding:.6rem 1rem;border-radius:6px}\n.skip:focus{left:.5rem}\n.up{color:var(--up)} .down{color:var(--down)} .flat{color:var(--muted)}\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums;font-size:.94em;white-space:nowrap}\n.meta{font-size:.8rem;color:var(--muted);letter-spacing:.01em}\n.kicker{display:inline-block;font-size:.72rem;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--teal);text-decoration:none;margin-bottom:.45rem}\na.kicker:hover{color:var(--amber-ink)}\n.kicker-sponsored{background:var(--amber-soft);color:var(--amber-ink);padding:.18rem .5rem;border-radius:4px;letter-spacing:.1em}\n.kicker-light{color:#f3d39d}\n\n/* Buttons */\n.btn{display:inline-flex;align-items:center;gap:.4rem;font:600 .92rem/1 var(--sans);padding:.8rem 1.15rem;border-radius:999px;text-decoration:none;border:1.5px solid transparent;transition:transform .15s ease,background .15s ease,color .15s ease;cursor:pointer}\n.btn:hover{transform:translateY(-1px);text-decoration:none}\n.btn-accent{background:var(--amber);color:#1b1206}\n.btn-accent:hover{background:#d99838;color:#1b1206}\n.btn-ghost{border-color:currentColor;color:var(--teal);background:transparent}\n.btn-ghost:hover{background:var(--teal);color:#fff;border-color:var(--teal)}\n.btn-sm{padding:.55rem .9rem;font-size:.82rem}\n\n/* Ticker tape */\n.tape{background:var(--deep);color:#d9e4e1;font-family:var(--mono);font-size:.76rem;overflow:hidden;border-bottom:1px solid #1f3a36}\n.tape-track{display:flex;width:max-content}\n.tape-row{display:flex;gap:2.2rem;padding:.5rem 1.1rem;white-space:nowrap}\n.tape-row[aria-hidden]{display:none}\n.tape .ti b{color:#fff;font-weight:500}\n.tape .up{color:var(--up-l)} .tape .down{color:var(--down-l)}\n.tape .asof{color:#8fa6a1}\n.js .tape-row[aria-hidden]{display:flex}\n.js .tape-track{animation:tape 55s linear infinite}\n.tape:hover .tape-track,.tape:focus-within .tape-track{animation-play-state:paused}\n@keyframes tape{to{transform:translateX(-50%)}}\n\n/* Header */\n.site-header{position:sticky;top:0;z-index:50;background:rgba(246,243,236,.92);backdrop-filter:saturate(1.4) blur(10px);-webkit-backdrop-filter:saturate(1.4) blur(10px);border-bottom:1px solid var(--rule)}\n.hdr{max-width:var(--maxw);margin:0 auto;padding:.7rem var(--gut);display:flex;align-items:center;gap:1rem}\n.logo{display:inline-flex;align-items:center;gap:.35rem;color:var(--ink);text-decoration:none;font:600 1.9rem/1 var(--serif);letter-spacing:-.02em}\n.logo:hover{color:var(--ink);text-decoration:none}\n.logo .mark{width:1.35rem;height:1.35rem;color:var(--amber);margin-top:.1rem;transition:transform .3s ease}\n.logo:hover .mark{transform:rotate(-12deg) scale(1.08)}\n.hdr-tag{font:italic 400 1rem/1.2 var(--serif);color:var(--muted);padding-left:1rem;border-left:1px solid var(--rule-2)}\n.hdr-tools{margin-left:auto;display:flex;align-items:center;gap:.6rem}\n.lang{display:inline-flex;border:1px solid var(--rule-2);border-radius:999px;padding:2px;font:600 .74rem/1 var(--sans);letter-spacing:.06em}\n.lang a,.lang span{display:inline-block;padding:.42rem .62rem;border-radius:999px;text-decoration:none;color:var(--ink-2);min-width:2.2rem;text-align:center}\n.lang span[aria-current]{background:var(--ink);color:#fff}\n.lang a:hover{background:var(--paper-2)}\n.menu-btn{display:none;width:2.6rem;height:2.6rem;border-radius:999px;border:1px solid var(--rule-2);background:var(--card);cursor:pointer;align-items:center;justify-content:center;color:var(--ink)}\n.menu-icon,.menu-icon::before,.menu-icon::after{display:block;width:1.05rem;height:2px;background:currentColor;border-radius:2px;position:relative;transition:transform .2s ease,background .2s}\n.menu-icon::before,.menu-icon::after{content:\"\";position:absolute;left:0}\n.menu-icon::before{top:-6px}.menu-icon::after{top:6px}\n.menu-btn[aria-expanded=\"true\"] .menu-icon{background:transparent}\n.menu-btn[aria-expanded=\"true\"] .menu-icon::before{transform:translateY(6px) rotate(45deg)}\n.menu-btn[aria-expanded=\"true\"] .menu-icon::after{transform:translateY(-6px) rotate(-45deg)}\nnav.sections{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut)}\nnav.sections ul{list-style:none;margin:0;padding:0;display:flex;gap:.25rem 1.6rem;flex-wrap:wrap}\nnav.sections a{display:inline-block;padding:.55rem 0 .65rem;font-size:.9rem;font-weight:500;color:var(--ink-2);text-decoration:none;border-bottom:2px solid transparent;white-space:nowrap}\nnav.sections a:hover{color:var(--ink);border-bottom-color:var(--rule-2)}\nnav.sections a[aria-current]{color:var(--ink);border-bottom-color:var(--amber)}\nnav.sections .nav-extra{display:none}\n@media (max-width:960px){.hdr-tag{display:none}}\n@media (max-width:820px){\n  .logo{font-size:1.6rem}\n  .menu-btn{display:inline-flex}\n  .hdr-nl{display:none}\n  /* no-JS: nav scrolls horizontally without clipping */\n  nav.sections ul{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;-webkit-mask-image:linear-gradient(90deg,#000 85%,transparent);mask-image:linear-gradient(90deg,#000 85%,transparent);padding-right:2rem}\n  nav.sections ul::-webkit-scrollbar{display:none}\n  .js nav.sections{display:none;padding-bottom:1rem}\n  .js .site-header.open nav.sections{display:block}\n  .js nav.sections ul{flex-direction:column;overflow:visible;-webkit-mask-image:none;mask-image:none;padding:0;gap:0}\n  .js nav.sections li{border-top:1px solid var(--rule)}\n  .js nav.sections a{display:block;padding:.85rem 0;font-size:1.05rem;border:0}\n  .js nav.sections a[aria-current]{color:var(--teal);font-weight:600}\n  .js nav.sections .nav-extra{display:block}\n}\n\n/* Hero */\n.hero{position:relative;min-height:clamp(30rem,72vh,44rem);display:flex;align-items:flex-end;color:#fff;background:var(--deep);overflow:hidden;isolation:isolate}\n.hero-media,.hero-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}\n.hero-media img{animation:heroZoom 18s ease-out both}\n@keyframes heroZoom{from{transform:scale(1.06)}to{transform:scale(1)}}\n.hero-shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(11,31,29,.15) 0%,rgba(11,31,29,.35) 40%,rgba(8,22,20,.92) 100%),linear-gradient(90deg,rgba(8,22,20,.7),rgba(8,22,20,0) 70%)}\n.hero-body{width:100%;padding-top:4rem;padding-bottom:clamp(2rem,5vw,3.5rem)}\n.hero-text{max-width:46rem}\n.hero .kicker{color:#f3d39d}\n.hero-title{font:600 clamp(2rem,4.6vw,3.6rem)/1.06 var(--serif);letter-spacing:-.02em;margin:.2rem 0 .9rem;text-wrap:balance}\n.hero-title a{color:#fff;text-decoration:none;background:linear-gradient(currentColor,currentColor) 0 100%/0 2px no-repeat;transition:background-size .35s ease}\n.hero-title a:hover{background-size:100% 2px}\n.hero-dek{font:400 clamp(1.05rem,1.7vw,1.3rem)/1.45 var(--serif);color:#e7eeec;margin:0 0 1.2rem;max-width:40rem}\n.hero-meta{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem 1rem;font-size:.82rem;color:#c5d3cf;margin-bottom:1.4rem}\n.hero .chip{background:rgba(255,255,255,.1);border-color:rgba(255,255,255,.22);color:#fff}\n.hero .chip b{color:#fff}\n.hero .chip .up{color:var(--up-l)} .hero .chip .down{color:var(--down-l)}\n\n/* Sections & cards */\n.section-head{display:flex;justify-content:space-between;align-items:baseline;gap:1rem;margin:3.5rem 0 1.4rem;padding-bottom:.7rem;border-bottom:1px solid var(--ink)}\n.section-head h2{font:600 1.55rem/1.1 var(--serif);margin:0;letter-spacing:-.01em}\n.section-head a.meta{color:var(--teal);text-decoration:none;font-weight:600}\n.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,19rem),1fr));gap:1.6rem}\n.card{background:var(--card);border-radius:var(--r);overflow:hidden;box-shadow:var(--shadow);display:flex;flex-direction:column;transition:transform .25s ease,box-shadow .25s ease}\n.card:hover{transform:translateY(-3px);box-shadow:0 2px 4px rgba(20,32,30,.06),0 18px 36px -16px rgba(20,32,30,.3)}\n.card-media{display:block;aspect-ratio:16/10;overflow:hidden;background:var(--paper-2)}\n.card-media img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}\n.card:hover .card-media img{transform:scale(1.04)}\n.card-body{padding:1.1rem 1.2rem 1.3rem;display:flex;flex-direction:column;flex:1}\n.card h3{font:600 1.28rem/1.2 var(--serif);margin:0 0 .5rem;letter-spacing:-.01em;text-wrap:balance}\n.card h3 a{color:var(--ink);text-decoration:none}\n.card h3 a:hover{color:var(--teal)}\n.card p{margin:0 0 .9rem;color:var(--ink-2);font-size:.94rem}\n.card .meta{margin-top:auto}\n.chips{display:flex;flex-wrap:wrap;gap:.35rem;margin-top:.7rem}\n.chip{display:inline-flex;gap:.35rem;align-items:baseline;font:400 .74rem/1 var(--mono);padding:.36rem .55rem;border:1px solid var(--rule);border-radius:999px;background:var(--paper);white-space:nowrap;color:var(--ink-2)}\n.chip b{font-weight:500;color:var(--ink)}\n.chips-col{flex-direction:column;align-items:flex-start}\n\n/* Markets */\n.quote{border:1px solid var(--rule);border-radius:var(--r);background:var(--card);margin:1.8rem 0;font-family:var(--sans);overflow:hidden;box-shadow:var(--shadow)}\n.quote-top{display:flex;justify-content:space-between;align-items:flex-start;gap:1rem;padding:1rem 1.1rem .4rem}\n.quote .sym{font-family:var(--mono);font-weight:500;font-size:.95rem}\n.quote .nm{font-size:.76rem;color:var(--muted)}\n.quote .px{font-family:var(--mono);font-size:1.6rem;line-height:1.1;text-align:right;font-variant-numeric:tabular-nums}\n.quote .px small{font-size:.72rem;color:var(--muted);margin-left:.25rem}\n.quote .chg{font-family:var(--mono);font-size:.86rem;text-align:right}\n.quote svg{display:block;width:100%;height:56px}\n.quote-foot{display:flex;flex-wrap:wrap;justify-content:space-between;gap:.3rem 1rem;border-top:1px solid var(--rule);padding:.55rem 1.1rem;font-size:.7rem;color:var(--muted);background:var(--paper)}\n.quote-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,16rem),1fr));gap:1rem;margin:1.8rem 0}\n.quote-grid .quote{margin:0}\n@media (min-width:700px){.markets .quote-grid{grid-template-columns:repeat(2,1fr)}}\n\n/* Category tiles */\n.tiles{display:grid;grid-template-columns:repeat(5,1fr);gap:1rem}\n.tile{position:relative;display:flex;align-items:flex-end;min-height:17rem;border-radius:var(--r);overflow:hidden;color:#fff;text-decoration:none;isolation:isolate;background:var(--deep)}\n.tile picture,.tile img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;transition:transform .6s ease}\n.tile:hover img{transform:scale(1.06)}\n.tile-shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(8,22,20,0) 25%,rgba(8,22,20,.9))}\n.tile-body{padding:1rem 1.05rem 1.1rem;display:flex;flex-direction:column;gap:.35rem}\n.tile-name{font:600 1.2rem/1.15 var(--serif)}\n.tile-desc{font-size:.8rem;line-height:1.4;color:#d6e1de;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}\n.tile-count{font:500 .7rem/1 var(--mono);color:#f3d39d;text-transform:uppercase;letter-spacing:.08em}\n.tile:hover{color:#fff}\n@media (max-width:1000px){.tiles{grid-template-columns:repeat(2,1fr)}.tile:first-child{grid-column:span 2}}\n@media (max-width:520px){.tiles{grid-template-columns:1fr}.tile:first-child{grid-column:auto}.tile{min-height:13rem}}\n\n/* Newsletter */\n.nl-band{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);background:var(--deep);color:#e8efed;border-radius:calc(var(--r) + 4px);overflow:hidden;margin:4rem 0 1rem;box-shadow:0 20px 50px -30px rgba(8,22,20,.7)}\n.nl-band.no-media{grid-template-columns:1fr}\n.nl-media{position:relative;min-height:16rem}\n.nl-media picture,.nl-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}\n.nl-body{padding:clamp(1.5rem,4vw,3rem)}\n.nl-band .kicker{color:#f3d39d}\n.nl-band h2{font:600 clamp(1.5rem,2.8vw,2.2rem)/1.12 var(--serif);margin:.1rem 0 .7rem;color:#fff;letter-spacing:-.01em}\n.nl-lead{margin:0 0 1.3rem;color:#c8d6d2;max-width:34rem}\n.nl-form{max-width:34rem}\n.nl-row{display:flex;gap:.5rem;flex-wrap:wrap}\n.nl-row input{flex:1 1 14rem;min-width:0;font:400 1rem/1.2 var(--sans);padding:.85rem 1.1rem;border-radius:999px;border:1.5px solid var(--rule-2);background:#fff;color:var(--ink)}\n.nl-row input:focus{border-color:var(--amber);outline:3px solid rgba(201,133,42,.35);outline-offset:1px}\n.nl-row input[aria-invalid=\"true\"]{border-color:var(--down)}\n.nl-row button{font:600 .95rem/1 var(--sans);padding:.85rem 1.3rem;border-radius:999px;border:0;background:var(--amber);color:#1b1206;cursor:pointer;transition:background .15s}\n.nl-row button:hover{background:#d99838}\n.nl-lang{border:0;margin:.8rem 0 0;padding:0;display:flex;gap:1rem;align-items:center;font-size:.85rem;flex-wrap:wrap}\n.nl-lang legend{float:left;margin-right:.4rem;color:inherit;opacity:.8;font-size:.8rem}\n.nl-lang label{display:inline-flex;gap:.35rem;align-items:center;cursor:pointer}\n.nl-lang input{accent-color:var(--amber);width:1rem;height:1rem}\n.nl-privacy{font-size:.76rem;line-height:1.5;margin:.8rem 0 0;opacity:.78}\n.nl-status{font-size:.88rem;margin:.6rem 0 0;font-weight:500;min-height:1em}\n.nl-status.ok{color:var(--up-l)} .nl-status.err{color:var(--down-l)}\n.nl-card{background:var(--deep);color:#e8efed;border-radius:var(--r);padding:1.5rem}\n.nl-card .nl-status.ok{color:var(--up-l)}\n.rail-nl .nl-status.ok{color:var(--up)} .rail-nl .nl-status.err{color:var(--down)}\n@media (max-width:820px){.nl-band{grid-template-columns:1fr}.nl-media{min-height:11rem}}\n\n/* Ads */\n.ad{position:relative;border:1px dashed var(--rule-2);border-radius:var(--r);padding:1.6rem 1.3rem 1.2rem;margin:2.4rem 0;background:repeating-linear-gradient(135deg,transparent 0 12px,rgba(20,32,30,.025) 12px 13px),var(--card);font-family:var(--sans);text-align:center}\n.ad-label{position:absolute;top:.55rem;left:.9rem;font:600 .62rem/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.ad-house p{margin:.4rem 0 .6rem;font:500 1.05rem/1.35 var(--serif);color:var(--ink-2)}\n.ad-cta{font-weight:600;font-size:.88rem;text-decoration:none}\n.ad-home_band{margin:3rem 0 0}\n\n/* Support strip */\n.support-strip{display:flex;align-items:center;justify-content:space-between;gap:1rem 2rem;flex-wrap:wrap;margin:3.5rem 0 0;padding:1.5rem 1.7rem;border-radius:var(--r);background:var(--amber-soft);border:1px solid #ecd3a6}\n.support-strip p{margin:0;font:500 1.15rem/1.4 var(--serif);max-width:44rem;color:#3d2b10}\n.support-strip .btn-ghost{color:var(--amber-ink)}\n.support-strip .btn-ghost:hover{background:var(--amber-ink);border-color:var(--amber-ink);color:#fff}\n\n/* Article */\n.article-head{max-width:52rem;margin:0 auto;padding:clamp(2rem,5vw,3.5rem) var(--gut) 1.6rem;text-align:center}\n.article-head .cats{font-weight:600;letter-spacing:.1em;text-transform:uppercase;font-size:.72rem}\n.article-head .cats a{text-decoration:none}\n.article-head h1{font:600 clamp(2rem,4.4vw,3.25rem)/1.08 var(--serif);letter-spacing:-.02em;margin:.7rem 0 .9rem;text-wrap:balance}\n.article-head .dek{font:400 clamp(1.1rem,1.8vw,1.35rem)/1.45 var(--serif);color:var(--ink-2);margin:0 auto 1.2rem;max-width:44rem}\n.byline{display:flex;justify-content:center;flex-wrap:wrap;gap:.3rem 1.2rem;font-size:.82rem;color:var(--muted)}\n.byline .by{font-weight:600;color:var(--ink)}\n.sponsor-banner{background:var(--amber-soft);border:1px solid #ecd3a6;border-radius:var(--r-sm);padding:.8rem 1rem;font-size:.88rem;margin-bottom:1.4rem;text-align:left}\n.sponsor-banner p{margin:.3rem 0 0;font-size:.8rem;color:#5a3d12}\n.figure{margin:0}\n.figure figcaption{font-size:.78rem;color:var(--muted);padding:.6rem 0 0;line-height:1.45}\n.figure .credit{white-space:nowrap;opacity:.8}\n.figure-hero{max-width:var(--maxw);margin:0 auto 2.5rem;padding:0 var(--gut)}\n.figure-hero picture{border-radius:var(--r);overflow:hidden;aspect-ratio:16/8;background:var(--paper-2)}\n.figure-hero img{width:100%;height:100%;object-fit:cover}\n.figure-inline{margin:2.2rem 0}\n.figure-inline picture{border-radius:var(--r-sm);overflow:hidden}\n.post-grid{max-width:var(--maxw);margin:0 auto;padding:0 var(--gut);display:grid;grid-template-columns:minmax(0,46rem);justify-content:center;gap:3.5rem}\n@media (min-width:1100px){.post-grid{grid-template-columns:minmax(0,46rem) 18rem}}\n.rail{display:none}\n@media (min-width:1100px){.rail{display:flex;flex-direction:column;gap:1.3rem;position:sticky;top:7.5rem;align-self:start}}\n.rail-box{background:var(--card);border:1px solid var(--rule);border-radius:var(--r);padding:1.1rem}\n.rail-box h2{font:600 .72rem/1 var(--sans);letter-spacing:.12em;text-transform:uppercase;margin:0 0 .8rem;color:var(--muted)}\n.rail-box p{font-size:.85rem;margin:0 0 .8rem;color:var(--ink-2)}\n.rail .ad{margin:0}\n.rail-nl .nl-row{flex-direction:column}\n.rail-nl .nl-row input,.rail-nl .nl-row button{flex:none;width:100%;padding:.7rem .9rem;font-size:.9rem}\n.rail-nl .nl-lang{font-size:.78rem;gap:.6rem}\n.rail-nl .nl-lang legend{display:none}\n.rail-nl .nl-privacy{font-size:.7rem}\n.prose{font:400 1.16rem/1.7 var(--serif);color:#1d2a27;min-width:0}\n.prose>p:first-of-type::first-letter{float:left;font-size:3.6em;line-height:.85;padding:.08em .1em 0 0;font-weight:600;color:var(--teal)}\n.prose h2{font:600 1.65rem/1.2 var(--serif);margin:2.6rem 0 .8rem;letter-spacing:-.01em}\n.prose h3{font:600 1.2rem/1.3 var(--sans);margin:2rem 0 .6rem}\n.prose p{margin:0 0 1.15rem}\n.prose ul,.prose ol{padding-left:1.3rem;margin:0 0 1.2rem}\n.prose li{margin:.35rem 0}\n.prose li::marker{color:var(--amber)}\n.prose blockquote{margin:1.6rem 0;padding:.4rem 0 .4rem 1.2rem;border-left:3px solid var(--amber);font-style:italic;color:var(--ink-2)}\n.prose .note,.note{background:#e8f0ed;border-left:3px solid var(--teal);border-radius:0 var(--r-sm) var(--r-sm) 0;padding:.9rem 1.1rem;margin:1.6rem 0;font:400 .95rem/1.55 var(--sans)}\n.note-inline{font:400 .9rem/1.55 var(--sans);color:var(--muted)}\n.tablewrap{overflow-x:auto;margin:1.6rem 0;border:1px solid var(--rule);border-radius:var(--r-sm);background:var(--card)}\n.prose table{border-collapse:collapse;width:100%;font:400 .86rem/1.4 var(--sans)}\n.prose th{text-align:left;font-weight:600;font-size:.72rem;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);background:var(--paper);padding:.65rem .8rem;border-bottom:1px solid var(--rule)}\n.prose td{padding:.6rem .8rem;border-bottom:1px solid var(--rule);vertical-align:top}\n.prose tr:last-child td{border-bottom:0}\n.prose td.r,.prose th.r{text-align:right;font-family:var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap}\n.facts{background:var(--card);border:1px solid var(--rule);border-top:3px solid var(--teal);border-radius:var(--r-sm);margin:0 0 2rem;padding:1.1rem 1.2rem;font:400 .88rem/1.45 var(--sans)}\n.facts dl{display:grid;grid-template-columns:auto 1fr;gap:.45rem 1.2rem;margin:0}\n.facts dt{color:var(--muted);font-size:.7rem;letter-spacing:.08em;text-transform:uppercase;padding-top:.18rem}\n.facts dd{margin:0}\n@media (max-width:520px){.facts dl{grid-template-columns:1fr}.facts dt{padding-top:.4rem}}\n.prose .quote{font-size:1rem;line-height:1.4}\n.post-end{max-width:46rem;margin:2.5rem auto 0;padding:0 var(--gut)}\n@media (min-width:1100px){.post-end{max-width:var(--maxw)}.post-end>*{max-width:46rem;margin-left:calc((100% - 46rem - 18rem - 3.5rem)/2)}}\n.sources{border-top:1px solid var(--ink);padding-top:1rem}\n.sources h2{font:600 .78rem/1 var(--sans);letter-spacing:.12em;text-transform:uppercase;margin:0 0 .8rem}\n.sources ol{font-size:.85rem;padding-left:1.3rem;margin:0;color:var(--ink-2)}\n.sources li{margin:.35rem 0;overflow-wrap:anywhere}\n.disclaimer-box{margin-top:1.6rem;font-size:.8rem;color:var(--muted);background:var(--paper-2);border-radius:var(--r-sm);padding:.9rem 1rem}\n.related{margin-bottom:1rem}\n\n/* Static pages */\n.page .prose-page{max-width:46rem;margin:0 auto;padding:0 var(--gut)}\n.prose-page>p:first-of-type::first-letter{all:unset}\n.page .figure-hero picture{aspect-ratio:16/6}\n.rate-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,13rem),1fr));gap:1rem;margin:1.5rem 0 1.8rem;font-family:var(--sans)}\n.prose-page .rate-cards{margin-left:calc(-1 * min(6vw,6rem));margin-right:calc(-1 * min(6vw,6rem))}\n@media (max-width:900px){.prose-page .rate-cards{margin-left:0;margin-right:0}}\n.rate{background:var(--card);border:1px solid var(--rule);border-radius:var(--r);padding:1.3rem 1.2rem;display:flex;flex-direction:column;box-shadow:var(--shadow)}\n.rate-featured{border:2px solid var(--teal);position:relative}\n.rate h3{font:600 1.05rem/1.25 var(--sans);margin:0 0 .5rem}\n.rate .price{font:600 1.9rem/1 var(--serif);margin:0 0 .9rem;color:var(--teal)}\n.rate .price span{font:400 .8rem var(--sans);color:var(--muted)}\n.rate ul{font-size:.86rem;line-height:1.45;margin:0 0 1rem;padding-left:1.1rem}\n.rate p:last-child{margin:auto 0 0}\n\n/* Banner (category / archive) */\n.page-banner{position:relative;color:#fff;background:var(--deep);isolation:isolate;overflow:hidden;min-height:17rem;display:flex;align-items:flex-end}\n.banner-media,.banner-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}\n.banner-shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(8,22,20,.92),rgba(8,22,20,.55) 60%,rgba(8,22,20,.3))}\n.banner-body{width:100%;padding-top:3rem;padding-bottom:2.2rem}\n.banner-body h1{font:600 clamp(2rem,4vw,3rem)/1.05 var(--serif);margin:.1rem 0 .6rem;letter-spacing:-.02em}\n.banner-body p{max-width:40rem;margin:0;color:#d6e1de;font:400 1.1rem/1.5 var(--serif)}\n.list-wrap{display:grid;grid-template-columns:minmax(0,1fr) 18rem;gap:3rem;padding-top:2.4rem;align-items:start}\n.list-wrap>.ad{position:sticky;top:7.5rem;margin:0}\n@media (max-width:1000px){.list-wrap{grid-template-columns:1fr}.list-wrap>.ad{position:static}}\n.list-item{display:grid;grid-template-columns:16rem minmax(0,1fr);gap:1.4rem;padding:1.4rem 0;border-bottom:1px solid var(--rule)}\n.list-item:first-child{padding-top:0}\n.list-media{display:block;aspect-ratio:16/10;border-radius:var(--r-sm);overflow:hidden;background:var(--paper-2)}\n.list-media img{width:100%;height:100%;object-fit:cover;transition:transform .5s ease}\n.list-item:hover .list-media img{transform:scale(1.04)}\n.list-item .kicker{margin:0}\n.list-item h2{font:600 1.4rem/1.2 var(--serif);margin:.35rem 0 .45rem;text-wrap:balance}\n.list-item h2 a{color:var(--ink);text-decoration:none}\n.list-item h2 a:hover{color:var(--teal)}\n.list-item p{margin:0;color:var(--ink-2);font-size:.95rem}\n@media (max-width:640px){.list-item{grid-template-columns:1fr;gap:.8rem}}\n.empty{color:var(--muted);font-style:italic}\n\n/* Footer */\nfooter.site{margin-top:5rem;background:var(--deep);color:#c3d1cd;font-size:.88rem}\n.foot-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:2rem;padding-top:3rem;padding-bottom:2.5rem}\nfooter.site h2{font:600 .7rem/1 var(--sans);letter-spacing:.14em;text-transform:uppercase;color:#8fa6a1;margin:0 0 1rem}\nfooter.site ul{list-style:none;margin:0;padding:0}\nfooter.site li{margin:.45rem 0}\nfooter.site a{color:#e8efed;text-decoration:none;overflow-wrap:anywhere}\nfooter.site a:hover{color:#f3d39d;text-decoration:underline}\n.logo-foot{color:#fff;font-size:2rem}\n.logo-foot:hover{color:#fff}\n.foot-tag{font:italic 400 1.05rem var(--serif);color:#d6e1de;margin:.5rem 0 1rem}\n.foot-small{font-size:.78rem;line-height:1.55;color:#9fb3ae;max-width:28rem}\n.foot-small a{text-decoration:underline!important}\n.foot-base{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.5rem 2rem;border-top:1px solid #23413c;padding-top:1.2rem;padding-bottom:1.6rem;font-size:.74rem;color:#8fa6a1}\n@media (max-width:820px){.foot-grid{grid-template-columns:1fr 1fr}.foot-brand{grid-column:1/-1}}\n\n/* Root chooser / 404 */\n.root-page{min-height:100vh;display:grid;place-items:center;background:var(--paper)}\n.root-choose{text-align:center;padding:2rem}\n.root-choose .logo{font-size:3rem}\n.root-choose .logo .mark{width:2rem;height:2rem}\n\n/* Reveal motion */\n.js .reveal{opacity:0;transform:translateY(14px);transition:opacity .6s ease,transform .6s ease}\n.js .reveal.in{opacity:1;transform:none}\n\n@media (prefers-reduced-motion:reduce){\n  *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}\n  .js .reveal{opacity:1;transform:none}\n  .js .tape-track{animation:none}\n  .js .tape-row[aria-hidden]{display:none}\n  .tape{overflow-x:auto}\n}\n@media print{\n  .tape,.site-header,footer.site,.ad,.nl-band,.rail,.related,.support-strip{display:none!important}\n  body{background:#fff}\n  .js .reveal{opacity:1;transform:none}\n}\n\n/* ---------- Subscription: paid badge, paywall gate, plan, account ---------- */\n.badge-paid{display:inline-flex;align-items:center;gap:.3rem;font:600 .68rem/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--amber-ink);background:var(--amber-soft);border:1px solid #ecd3a6;padding:.26rem .5rem .24rem .42rem;border-radius:999px;white-space:nowrap;vertical-align:.08em}\n.badge-paid svg{display:inline-block;width:.78rem;height:.78rem;flex:none}\n.hero-meta .badge-paid{background:rgba(246,230,203,.95)}\n.kicker .badge-paid{font-size:.7rem}\n.btn-lg{padding:1rem 1.5rem;font-size:1rem}\n.btn[disabled],.btn[aria-disabled=\"true\"]{opacity:.55;cursor:not-allowed;transform:none}\n\n.paywall{position:relative;margin:2rem 0 1rem;font-family:var(--sans)}\n.pw-fade{position:absolute;left:0;right:0;top:-3rem;height:3rem;background:linear-gradient(to bottom,rgba(246,243,236,0),var(--paper));pointer-events:none}\n.pw-card{background:var(--card);border:1px solid var(--rule);border-top:4px solid var(--amber);border-radius:var(--r);box-shadow:var(--shadow);padding:clamp(1.3rem,3vw,2rem)}\n.pw-card .kicker{margin:0 0 .6rem}\n.prose .pw-card h2{font:600 clamp(1.35rem,2.4vw,1.7rem)/1.18 var(--serif);margin:0 0 .7rem;letter-spacing:-.01em}\n.prose .pw-card p{font:400 1rem/1.55 var(--sans);margin:0 0 1rem;color:var(--ink-2)}\n.pw-next{border-left:3px solid var(--teal);padding:.2rem 0 .2rem 1rem;margin:0 0 1.2rem}\n.prose .pw-next-h{font:600 .72rem/1 var(--sans);letter-spacing:.12em;text-transform:uppercase;color:var(--teal);margin:0 0 .5rem}\n.prose .pw-next ul{margin:0;padding-left:1.1rem;font:500 .95rem/1.5 var(--serif);color:var(--ink)}\n.prose .pw-price{font-size:.92rem;color:var(--ink)}\n.pw-form{margin:0 0 1rem}\n.prose .pw-links{font-size:.88rem;margin:0}\n.prose .pw-status{font-size:.86rem;color:var(--muted);margin:.8rem 0 0}\n.prose .pw-status:empty{display:none}\n.paywall.is-unlocked{display:none}\n.paid-body{animation:pwIn .5s ease both}\n@keyframes pwIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.paid-body{animation:none}}\n\n.plan{background:var(--card);border:2px solid var(--teal);border-radius:var(--r);box-shadow:var(--shadow);padding:clamp(1.3rem,3vw,2.2rem);margin:1.8rem 0 2.2rem;font-family:var(--sans)}\n.plan-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:.2rem 1rem;margin-bottom:1rem}\n.plan-head .kicker{width:100%;margin:0}\n.prose .plan-price{font:600 clamp(2.4rem,5vw,3.2rem)/1 var(--serif);color:var(--teal);margin:0;letter-spacing:-.02em}\n.plan-price span{font:500 1rem/1 var(--sans);color:var(--muted);letter-spacing:0}\n.prose .plan-sub{margin:0;font-size:.9rem;color:var(--ink-2)}\n.prose .plan-list{list-style:none;padding:0;margin:0 0 1.4rem;font:400 1rem/1.5 var(--sans)}\n.prose .plan-list li{position:relative;padding-left:1.7rem;margin:.45rem 0}\n.prose .plan-list li::before{content:\"\";position:absolute;left:.15rem;top:.5em;width:.75rem;height:.4rem;border-left:2px solid var(--amber);border-bottom:2px solid var(--amber);transform:rotate(-45deg)}\n.sub-form{margin:0 0 1rem}\n.prose .plan-fine{font-size:.84rem;line-height:1.5;color:var(--muted);margin:.7rem 0 0}\n.prose .plan .note{margin:1rem 0}\n\n.account{font-family:var(--sans);margin:.5rem 0 2rem}\n.acct-card{background:var(--card);border:1px solid var(--rule);border-top:4px solid var(--teal);border-radius:var(--r);box-shadow:var(--shadow);padding:clamp(1.3rem,3vw,2rem);margin:0 0 1.5rem}\n.prose .acct-card h2{font:600 1.5rem/1.2 var(--serif);margin:0 0 .6rem}\n.prose .acct-card p{font:400 1rem/1.55 var(--sans);margin:0 0 1rem}\n.acct-card form{margin:0 0 .6rem}\n.acct-card form+form{margin-top:1.2rem}\n.acct-device{border-top:1px solid var(--rule);padding-top:1.2rem;margin-top:1.8rem}\n.prose .acct-device h2{font:600 1.15rem/1.3 var(--sans);margin:0 0 .5rem}\n.prose .acct-device p{font-size:.94rem;color:var(--ink-2)}\n[hidden]{display:none!important}\n\n.hdr-sub{margin-right:.4rem}\n@media (max-width:820px){.hdr-sub{display:none}}\n";
